/**
 * Reading a whole document (views/reader.js): the markers generated by the
 * server in the UI language, the entries of the "Page" list and the page
 * being read. Creates no DOM node, so that tests run in Node.
 */
import { t } from './i18n.js';
import { pageShortLabel } from './labels.js';

/** Marker at the start of a page: "Page 42", "Page 42–43", or "Unnumbered page" for an empty label. */
export function pageMarkerText(label) {
  return label ? t('Page {label}', { label }) : t('Unnumbered page');
}

/** Gap in the numbering: "Missing pages: 13–44", "Missing page: 13". */
export function missingPagesText(range) {
  return /[–-]/.test(range) ? t('Missing pages: {range}', { range }) : t('Missing page: {range}', { range });
}

/** Heading before the pages that could not be placed. */
export function unnumberedHeadingText() {
  return t('Unnumbered pages');
}

/**
 * Writes the markers of the document HTML (GET /api/documents/{id}/html,
 * children of `content`) in the UI language. The server writes them in
 * English and gives their data as attributes:
 * <p class="page-marker" data-label="42"> (empty for a page without number),
 * <p class="missing-pages" data-range="13–44"> and <h2 class="unnumbered">.
 * A marker without its attribute keeps the server's text.
 */
export function localizeMarkers(content) {
  for (const element of content.children) {
    if (element.matches('section.page')) {
      const marker = element.querySelector(':scope > .page-marker');
      const label = marker?.getAttribute('data-label') ?? null;
      if (label !== null) marker.textContent = pageMarkerText(label);
    } else if (element.matches('.missing-pages')) {
      const range = element.getAttribute('data-range');
      if (range !== null) element.textContent = missingPagesText(range);
    } else if (element.matches('h2.unnumbered')) {
      element.textContent = unnumberedHeadingText();
    }
  }
}

/**
 * Entries of the "Page" list, from the parts of the document HTML in reading
 * order: `{ type: 'page', key, marker }` (marker: the page marker),
 * `{ type: 'gap', text }` (missing pages) and `{ type: 'heading', text }`
 * (the unnumbered pages follow it). `pagesByKey` maps page keys to Page
 * objects of the API.
 *
 * Returns `{ type: 'page', index, key, page, label }` (index: rank in the
 * reading order; page: null when unknown), `{ type: 'gap', label }` and
 * `{ type: 'group', label }`. Pages without number are told apart by their
 * rank, "p. 12" being enough for the others.
 */
export function readingOutline(parts, pagesByKey) {
  const entries = [];
  let index = 0;
  for (const part of parts) {
    if (part.type === 'gap') {
      entries.push({ type: 'gap', label: part.text });
    } else if (part.type === 'heading') {
      entries.push({ type: 'group', label: part.text });
    } else if (part.type === 'page') {
      const page = pagesByKey.get(part.key) ?? null;
      let label = part.marker;
      if (page) {
        label = page.page_label
          ? pageShortLabel(page)
          : t('{label} (position {position})', { label: pageShortLabel(page), position: index + 1 });
      }
      entries.push({ type: 'page', index, key: part.key, page, label });
      index += 1;
    }
  }
  return entries;
}

/**
 * Index of the page being read among `count` pages laid out top to bottom:
 * the last one whose top (`topOf(index)`, increasing with the index) has
 * reached `line`; 0 before the first one. Binary search: a long book has
 * hundreds of pages, and this runs while scrolling.
 */
export function pageAtLine(count, topOf, line) {
  let low = 0;
  let high = count - 1;
  let found = 0;
  while (low <= high) {
    const middle = Math.floor((low + high) / 2);
    if (topOf(middle) <= line) {
      found = middle;
      low = middle + 1;
    } else {
      high = middle - 1;
    }
  }
  return found;
}
